TEXT_CANDIDATES = [
    "summary.txt",
    "stdout.log",
    "stderr.log",
    "console.log",
    "train.log",
    "test.log",
    "eval.log",
]

METADATA_COLUMNS = {
    "experiment_id", "attempt_id", "study_id", "plan_id", "suite", "method", "case",
    "dataset", "split", "fold", "seed", "epoch", "step", "timestamp", "run_id",
    "global_job_id", "job_dir", "checkpoint_path", "config_path", "run_status",
}

LOWER_IS_BETTER_METRICS = {"loss", "log_loss", "cross_entropy", "ce_loss", "asd", "hd95", "mae", "mse", "rmse", "error", "ece", "brier", "brier_score", "fpr", "fnr"}
# 常见别名示例：val_auc、test_acc、best_f1、train_loss、macro_auc 会自动归一到分类指标。

def load_zlk_project_context(project_root=None):
    """读取 experiments/zlk_project.yaml 中的轻量结果捕获配置；不依赖 PyYAML。"""
    root = Path(project_root or Path.cwd())
    config = root / "experiments" / "zlk_project.yaml"
    if not config.exists():
        return {}
    lines = config.read_text(encoding="utf-8", errors="ignore").splitlines()
    out = {}
    def section_list(name):
        values = []
        active = False
        for raw in lines:
            if re.match(rf"^\s{{2}}{re.escape(name)}:\s*$", raw):
                active = True
                continue
            if active and re.match(r"^\s{2}[A-Za-z0-9_-]+:\s*", raw):
                break
            if active:
                m = re.match(r"^\s*-\s*(.+?)\s*$", raw)
                if m:
                    values.append(m.group(1).strip().strip('"\''))
        return values
    def scalar(name):
        for raw in lines:
            m = re.match(rf"^\s{{2}}{re.escape(name)}:\s*(.+?)\s*$", raw)
            if m:
                return m.group(1).strip().strip('"\'')
        return ""
    out["extra_csv_paths"] = section_list("candidateCsv")
    out["extra_json_paths"] = section_list("candidateJson")
    out["console_logs"] = section_list("consoleLogs") + section_list("textLogs")
    if scalar("metricRegex"):
        out["metric_regex"] = scalar("metricRegex")
    return {k: v for k, v in out.items() if v}

def write_env_snapshot(path, command="", seed=""):
    import subprocess
    import sys
    try:
        import torch
    except Exception:
        torch = None
    data = {
        "schemaVersion": 1,
        "git_commit": subprocess.getoutput("git rev-parse HEAD"),
        "git_dirty": bool(subprocess.getoutput("git status --porcelain")),
        "python": sys.version.split()[0],
        "torch": getattr(torch, "__version__", "") if torch else "",
        "cuda": getattr(getattr(torch, "version", None), "cuda", "") if torch else "",
        "gpu_name": torch.cuda.get_device_name(0) if torch and torch.cuda.is_available() else "",
        "command": command,
        "seed": seed,
    }
    with open(path, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2)

def pick(row, *keys, default=""):
    lowered = {str(k).lower(): v for k, v in row.items()}
    for key in keys:
        if key in row and row[key] not in (None, ""):
            return row[key]
        value = lowered.get(str(key).lower())
        if value not in (None, ""):
            return value
    return default

def numberish(value):
    try:
        float(str(value).strip())
        return True
    except Exception:
        return False

def read_csv_rows(path):
    import csv
    path = Path(path)
    if not path.exists() or not path.is_file():
        return []
    with open(path, newline="", encoding="utf-8-sig") as f:
        return list(csv.DictReader(f))

def read_json_value(path):
    path = Path(path)
    if not path.exists() or not path.is_file():
        return None
    try:
        with open(path, encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None

def looks_like_metric_column(name):
    lower = str(name).lower()
    if lower in METADATA_COLUMNS:
        return False
    tokens = ["accuracy", "acc", "top1", "top_1", "top5", "top_5", "auc", "auroc", "roc_auc", "auprc", "pr_auc", "average_precision", "ap", "f1", "macro_f1", "micro_f1", "weighted_f1", "f1_macro", "f1_micro", "f1_weighted", "precision", "macro_precision", "micro_precision", "weighted_precision", "recall", "macro_recall", "micro_recall", "weighted_recall", "sensitivity", "specificity", "balanced_accuracy", "balanced_acc", "bal_acc", "mcc", "matthews_corrcoef", "kappa", "cohen_kappa", "npv", "ppv", "fpr", "fnr", "loss", "log_loss", "cross_entropy", "ce_loss", "ece", "brier", "brier_score", "dice", "dsc", "iou", "hd95", "asd", "mae", "mse", "rmse"]
    return any(token in lower for token in tokens)

def normalize_metric_name(metric):
    lower = str(metric).strip().lower()
    parts = [p for p in re.split(r"[_.\s-]+", lower) if p]
    split_words = {"train", "val", "valid", "validation", "test", "external", "ext"}
    decorators = {"best", "final", "last", "mean", "avg", "average", "eval", "score", "metric", "macro", "micro", "weighted"}
    if parts and parts[0] in split_words:
        parts = parts[1:]
    if parts and parts[-1] in split_words:
        parts = parts[:-1]
    compact = "_".join(parts)
    stripped = "_".join([p for p in parts if p not in decorators])
    lower = compact
    if stripped in {"auc", "auroc", "roc_auc", "auprc", "pr_auc", "average_precision", "ap", "acc", "accuracy", "f1", "precision", "recall", "specificity", "sensitivity", "tpr", "tnr", "mcc", "matthews_corrcoef", "cohen_kappa", "brier", "brier_score", "loss", "log_loss", "cross_entropy", "ce_loss", "dice", "dsc", "iou", "hd95", "asd", "mae", "mse", "rmse", "r2"}:
        lower = stripped
    if lower == "acc":
        return "accuracy"
    if lower in {"top1", "top_1", "top1_acc", "top1_accuracy"}:
        return "top1_accuracy"
    if lower in {"top5", "top_5", "top5_acc", "top5_accuracy"}:
        return "top5_accuracy"
    if lower in {"auc", "auroc", "roc_auc"}:
        return "AUC"
    if lower in {"auprc", "pr_auc", "average_precision", "ap"}:
        return "AUPRC"
    if lower in {"macro_f1", "micro_f1", "weighted_f1", "f1_macro", "f1_micro", "f1_weighted"}:
        return "F1"
    if lower in {"macro_precision", "micro_precision", "weighted_precision"}:
        return "precision"
    if lower in {"macro_recall", "micro_recall", "weighted_recall"}:
        return "recall"
    if lower in {"balanced_acc", "bal_acc"}:
        return "balanced_accuracy"
    if lower in {"sensitivity", "tpr"}:
        return "recall"
    if lower in {"tnr"}:
        return "specificity"
    if lower in {"ppv"}:
        return "precision"
    if lower in {"mcc", "matthews_corrcoef"}:
        return "MCC"
    if lower in {"cohen_kappa"}:
        return "kappa"
    if lower in {"brier_score"}:
        return "brier"
    if lower in {"log_loss", "cross_entropy", "ce_loss"}:
        return "loss"
    if lower in {"dice", "dsc"}:
        return "DSC"
    if lower in {"iou"}:
        return "IoU"
    if lower in {"mae", "mse", "rmse"}:
        return lower.upper()
    if lower in {"r2"}:
        return "R2"
    return str(metric).strip()

def summary_row(row, metric, value, context, source_path=""):
    metric = str(metric).strip()
    if not metric or value in (None, ""):
        return None
    return {
        "experiment_id": pick(row, "experiment_id", "experiment_name", "run_id", "global_job_id", default=context.get("experiment_id", "unknown")),
        "attempt_id": pick(row, "attempt_id", "run_id", default=context.get("attempt_id", "attempt-1")),
        "study_id": pick(row, "study_id", default=context.get("study_id", "")),
        "plan_id": pick(row, "plan_id", default=context.get("plan_id", "")),
        "suite": pick(row, "suite", default=context.get("suite", "__ZLK_PROJECT_NAME__")),
        "method": pick(row, "method", "case", default=context.get("method", "ours")),
        "dataset": pick(row, "dataset", default=context.get("dataset", "unknown")),
        "split": pick(row, "split", default=context.get("split", "test")),
        "fold": pick(row, "fold", default=context.get("fold", "")),
        "seed": pick(row, "seed", default=context.get("seed", "")),
        "metric": metric,
        "value": value,
        "unit": pick(row, "unit", default=""),
        "higher_is_better": str(metric).lower() not in LOWER_IS_BETTER_METRICS,
        "epoch": pick(row, "epoch", default=context.get("epoch", "")),
        "step": pick(row, "step", default=context.get("step", "")),
        "timestamp": pick(row, "timestamp", default=context.get("timestamp", "")),
    }

def normalize_csv_rows(path, rows, context):
    if not rows:
        return []
    headers = list(rows[0].keys())
    lower_headers = {str(h).lower() for h in headers}
    normalized = []
    if "metric" in lower_headers and "value" in lower_headers:
        for row in rows:
            item = summary_row(row, pick(row, "metric"), pick(row, "value"), context, str(path))
            if item:
                normalized.append(item)
        return normalized
    metric_columns = [h for h in headers if looks_like_metric_column(h)]
    for row in rows:
        for metric in metric_columns:
            value = row.get(metric, "")
            if numberish(value):
                item = summary_row(row, metric, value, context, str(path))
                if item:
                    normalized.append(item)
    return normalized

def iter_candidate_csv_paths(output_dir, context):
    output_dir = Path(output_dir)
    for pattern in SUMMARY_CANDIDATES:
        yield from output_dir.glob(pattern)
    extras = [context.get("result_csv"), context.get("results_csv"), context.get("metrics_csv")]
    extra_csv_paths = context.get("extra_csv_paths") or []
    if isinstance(extra_csv_paths, (str, Path)):
        extra_csv_paths = [extra_csv_paths]
    extras.extend(extra_csv_paths)
    for item in extras:
        if not item:
            continue
        candidate = Path(item)
        yield candidate
        if not candidate.is_absolute():
            yield output_dir / candidate

def discover_csv_metrics(output_dir, context):
    rows = []
    seen = set()
    for path in iter_candidate_csv_paths(output_dir, context):
        key = str(Path(path).resolve())
        if key in seen:
            continue
        seen.add(key)
        rows.extend(normalize_csv_rows(path, read_csv_rows(path), context))
    return rows

def metric_items_from_json(row):
    if not isinstance(row, dict):
        return []
    for key in ["metrics", "metric_values", "scores", "summary"]:
        value = row.get(key)
        if isinstance(value, dict):
            return [(metric, raw) for metric, raw in value.items() if numberish(raw)]
    return [(metric, raw) for metric, raw in row.items() if metric not in METADATA_COLUMNS and numberish(raw)]

def normalize_json_metrics(value, context, source_path=""):
    rows = []
    if isinstance(value, list):
        for item in value:
            rows.extend(normalize_json_metrics(item, context, source_path))
        return rows
    if not isinstance(value, dict):
        return rows
    for key in ["results", "records", "runs", "items"]:
        if isinstance(value.get(key), list):
            parent = {k: v for k, v in value.items() if k != key and not isinstance(v, (list, dict))}
            for item in value[key]:
                if isinstance(item, dict):
                    merged = dict(parent)
                    merged.update(item)
                    rows.extend(normalize_json_metrics(merged, context, source_path))
            return rows
    for metric, raw in metric_items_from_json(value):
        item = summary_row(value, metric, raw, context, source_path)
        if item:
            rows.append(item)
    return rows

def iter_candidate_json_paths(output_dir, context):
    output_dir = Path(output_dir)
    for pattern in JSON_CANDIDATES:
        yield from output_dir.glob(pattern)
    extras = [context.get("result_json"), context.get("results_json"), context.get("metrics_json")]
    extra_json_paths = context.get("extra_json_paths") or []
    if isinstance(extra_json_paths, (str, Path)):
        extra_json_paths = [extra_json_paths]
    extras.extend(extra_json_paths)
    for item in extras:
        if not item:
            continue
        candidate = Path(item)
        yield candidate
        if not candidate.is_absolute():
            yield output_dir / candidate

def discover_json_metrics(output_dir, context):
    rows = []
    seen = set()
    for path in iter_candidate_json_paths(output_dir, context):
        base = Path(path).name.lower()
        if base in {"artifact_manifest.json", "checkpoint_manifest.json", "manifest.json", "metadata.json", "status.json", "state.json", "progress.json", "job.json", "jobs.json", "env_snapshot.json", "config_snapshot.json"} or re.search(r"(?:_snapshot|_manifest|_status|_state|_progress)\.json$", base):
            continue
        key = str(Path(path).resolve())
        if key in seen:
            continue
        seen.add(key)
        rows.extend(normalize_json_metrics(read_json_value(path), context, str(path)))
    return rows

METRIC_PATTERN = re.compile(
    r"\b(?P<metric>(?:(?:train|val|valid|validation|test|external|ext|best|final|last|mean|avg|macro|micro|weighted|eval)[_-]){0,3}(?:accuracy|acc|top1|top_1|top1_acc|top1_accuracy|top5|top_5|top5_acc|top5_accuracy|auc|auroc|roc_auc|auprc|pr_auc|average_precision|ap|f1|macro_f1|micro_f1|weighted_f1|f1_macro|f1_micro|f1_weighted|precision|macro_precision|micro_precision|weighted_precision|recall|macro_recall|micro_recall|weighted_recall|sensitivity|specificity|balanced_accuracy|balanced_acc|bal_acc|mcc|matthews_corrcoef|kappa|cohen_kappa|npv|ppv|fpr|fnr|loss|log_loss|cross_entropy|ce_loss|ece|brier|brier_score|dice|dsc|iou|hd95|asd|mae|mse|rmse|r2)(?:[_-](?:train|val|valid|validation|test|external|ext|best|final|last|mean|avg|macro|micro|weighted|eval)){0,3})\b"
    r"\s*[:=]\s*(?P<value>-?\d+(?:\.\d+)?(?:e[+-]?\d+)?)(?P<percent>\s*%)?",
    re.IGNORECASE,
)

def metric_pattern_from_context(context):
    pattern = context.get("metric_regex")
    if pattern:
        try:
            return re.compile(pattern, re.IGNORECASE)
        except Exception:
            pass
    return METRIC_PATTERN

def capture_console_metrics(text, context):
    """从 stdout/stderr 中捕获常见深度学习指标。"""
    rows = []
    for match in metric_pattern_from_context(context).finditer(text or ""):
        metric = normalize_metric_name(match.group("metric"))
        value = float(match.group("value"))
        if match.groupdict().get("percent"):
            value = value / 100.0
        rows.append({
            "experiment_id": context.get("experiment_id", "unknown"),
            "attempt_id": context.get("attempt_id", "attempt-1"),
            "study_id": context.get("study_id", ""),
            "plan_id": context.get("plan_id", ""),
            "suite": context.get("suite", "__ZLK_PROJECT_NAME__"),
            "method": context.get("method", "ours"),
            "dataset": context.get("dataset", "unknown"),
            "split": context.get("split", "test"),
            "fold": context.get("fold", ""),
            "seed": context.get("seed", ""),
            "metric": metric,
            "value": value,
            "unit": "",
            "higher_is_better": metric.lower() not in LOWER_IS_BETTER_METRICS,
            "epoch": context.get("epoch", ""),
            "step": context.get("step", ""),
            "timestamp": context.get("timestamp", ""),
        })
    return rows

def iter_candidate_text_paths(output_dir, context):
    output_dir = Path(output_dir)
    for pattern in TEXT_CANDIDATES:
        yield from output_dir.glob(pattern)
    extras = context.get("console_logs") or []
    if isinstance(extras, (str, Path)):
        extras = [extras]
    for item in extras:
        if not item:
            continue
        candidate = Path(item)
        yield candidate
        if not candidate.is_absolute():
            yield output_dir / candidate

def discover_text_metrics(output_dir, context):
    rows = []
    seen = set()
    for path in iter_candidate_text_paths(output_dir, context):
        key = str(Path(path).resolve())
        if key in seen:
            continue
        seen.add(key)
        path = Path(path)
        if path.exists() and path.is_file():
            rows.extend(capture_console_metrics(path.read_text(encoding="utf-8", errors="ignore"), context))
    return rows

def dedupe_rows(rows):
    out = []
    seen = set()
    for row in rows:
        key = tuple(str(row.get(k, "")) for k in ["experiment_id", "suite", "method", "dataset", "split", "fold", "seed", "metric", "epoch", "step"])
        if key in seen:
            continue
        seen.add(key)
        out.append(row)
    return out

class OutputAdapterRegistry:
    def __init__(self):
        self._items = {}

    def register(self, name, adapter_cls):
        self._items[name] = adapter_cls
        return adapter_cls

    def build(self, name="default", **kwargs):
        cls = self._items.get(name)
        if cls is None:
            raise KeyError(f"unknown output adapter: {name}")
        return cls(**kwargs)

registry = OutputAdapterRegistry()

def register_adapter(name):
    def deco(cls):
        registry.register(name, cls)
        return cls
    return deco

@register_adapter("default")
class DefaultDeepLearningAdapter:
    def collect(self, output_dir, context=None, stdout_text="", stderr_text=""):
        context = dict(context or {})
        output_dir = Path(output_dir)
        output_dir.mkdir(parents=True, exist_ok=True)
        summary_rows = []
        summary_rows.extend(discover_csv_metrics(output_dir, context))
        summary_rows.extend(discover_json_metrics(output_dir, context))
        summary_rows.extend(discover_text_metrics(output_dir, context))
        summary_rows.extend(capture_console_metrics(stdout_text, context))
        summary_rows.extend(capture_console_metrics(stderr_text, context))
        summary_rows = dedupe_rows(summary_rows)
        if summary_rows:
            write_metrics_summary(output_dir / "metrics_summary.csv", summary_rows)
        write_env_snapshot(output_dir / "env_snapshot.json", context.get("command", ""), context.get("seed", ""))
        (output_dir / "config_snapshot.yaml").write_text(context.get("config_text", ""), encoding="utf-8")
        files = [p.name for p in [output_dir / "metrics_summary.csv", output_dir / "env_snapshot.json", output_dir / "config_snapshot.yaml"] if p.exists()]
        manifest = {
            "schemaVersion": 1,
            "files": files,
            "note": "checkpoint 和大权重文件不建议默认同步到本机。",
        }
        (output_dir / "artifact_manifest.json").write_text(json.dumps(manifest, indent=2), encoding="utf-8")
        return manifest

def collect_outputs(output_dir, context=None, stdout_text="", stderr_text="", adapter="default", extra_csv_paths=None):
    config_context = load_zlk_project_context()
    context = {**config_context, **dict(context or {})}
    if extra_csv_paths is not None:
        context["extra_csv_paths"] = extra_csv_paths
    return registry.build(adapter).collect(output_dir, context=context, stdout_text=stdout_text, stderr_text=stderr_text)

